536	func runReceipt(args []string) {
537		cf := newCmdFlags("receipt")
538		id := cf.fs.String("id", "", "proposal id")
539		cf.parse(args)
540		if *id == "" {
541			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
542			os.Exit(2)
543		}
544		store, err := govflow.Open(cf.state)
545		if err != nil {
546			fail(err)
547		}
548		defer store.Close()
549		receipt, ok, err := store.Receipt(*id)
550		if err != nil {
551			fail(err)
552		}
553		if !ok {
554			fail(fmt.Errorf("no execution receipt for proposal %s", *id))
555		}
556		if cf.asJSON {
557			emitJSON(receipt)
558			return
559		}
560		printReceiptText(receipt, true)
561	}
562	
563	func runReceipts(args []string) {
564		cf := newCmdFlags("receipts")
565		cf.parse(args)
566		store, err := govflow.Open(cf.state)
567		if err != nil {
568			fail(err)
569		}
570		defer store.Close()
571		receipts, err := store.Receipts()
572		if err != nil {
573			fail(err)
574		}
575		if cf.asJSON {
576			emitJSON(receipts)
577			return
578		}
579		for _, receipt := range receipts {
580			printReceiptText(receipt, true)
581		}
582	}
583	
584	func printProposalText(p govflow.ProposalRecord) {
585		fmt.Printf("proposal %s state=%s timelock_end=%d actions=%d\n", p.ID, p.State, p.TimelockEnd, len(p.Actions))
586		for i, action := range p.Actions {
587			fmt.Printf("  action %d: %s\n", i, action)
588		}
589	}
590	
591	func printVoteProposalText(v *govflow.VoteProposalView) {
592		fmt.Printf("proposal %s source=vote state=%s quorum=%d voting=[%d,%d) timelock_end=%d actions=%d total_weight=%d\n",
593			v.ID, v.State, v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd, len(v.Actions), v.TotalWeight)
594		for _, m := range v.Members {
595			chain := strings.Join(m.Path, "->")
596			if len(m.Path) == 1 {
597				fmt.Printf("  member %s weight=%d representative=self\n", m.ID, m.Weight)
598			} else {
599				fmt.Printf("  member %s weight=%d path=%s\n", m.ID, m.Weight, chain)
600			}
601		}
602		for i, action := range v.Actions {
603			fmt.Printf("  action %d: %s\n", i, action)
604		}
605		for _, b := range v.Ballots {
606			fmt.Printf("  ballot representative=%s choice=%s weight=%d voted_at=%d\n",
607				b.Representative, choiceWord(b.Support), b.Weight, b.VotedAt)
608		}
609		if v.Tally != nil {
610			verdict := "rejected"
611			if v.Tally.Passed {
612				verdict = "passed"
613			}
614			fmt.Printf("  tally for=%d against=%d turnout=%d => %s tallied_at=%d\n",
615				v.Tally.ForWeight, v.Tally.AgainstWeight, v.Tally.Turnout, verdict, v.Tally.TalliedAt)
616		}
617	}
618	
619	func printReceiptText(r *govflow.Receipt, header bool) {
620		if header {
621			fmt.Printf("receipt proposal=%s order=%d executed_at=%d actions=%d\n", r.ProposalID, r.Order, r.ExecutedAt, len(r.Actions))
622		} else {
623			fmt.Printf("executed proposal %s at %d (%d action(s)); receipt order %d\n", r.ProposalID, r.ExecutedAt, len(r.Actions), r.Order)
624		}
625		for _, ar := range r.Actions {
626			fmt.Printf("  action %d: %s\n", ar.Index, ar.Action)
627			fmt.Printf("    treasury:  %d -> %d\n", ar.Treasury.Before, ar.Treasury.After)
628			fmt.Printf("    %s: %d -> %d\n", ar.Recipient.Account, ar.Recipient.Before, ar.Recipient.After)
629		}
630	}
631	
632	func runDemo() {
633		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
634			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
635		if err := govflow.Vote(&proposal, 700, true); err != nil {
636			fmt.Println("vote refused:", err)
637		}
638		if err := govflow.Vote(&proposal, 200, false); err != nil {
639			fmt.Println("vote refused:", err)
640		}
641		next := govflow.Tally(&proposal)
642		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
643		proposal.State = next
644		proposal.TimelockEnd = 400
645		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
