607	// BalanceSnapshot 在一次持锁读取中取得资金库与全部收款账户余额。
608	// 返回的 Balances 是副本（永不为 nil），调用方可自由使用；
609	// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
610	func (s *Store) BalanceSnapshot() (*BalanceSnapshot, error) {
611		state, err := s.readState()
612		if err != nil {
613			return nil, err
614		}
615		out := &BalanceSnapshot{
616			Treasury: state.Treasury,
617			Balances: make(map[string]int64, len(state.Balances)),
618		}
619		for k, v := range state.Balances {
620			out.Balances[k] = v
621		}
622		return out, nil
623	}
