656	// Proposal 按编号返回提案登记信息；不存在时 ok 为 false。
657	func (s *Store) Proposal(id string) (ProposalRecord, bool, error) {
658		state, err := s.readState()
659		if err != nil {
660			return ProposalRecord{}, false, err
661		}
662		p, ok := state.Proposals[id]
663		if !ok {
664			return ProposalRecord{}, false, nil
665		}
666		return toProposalRecord(p), true, nil
667	}
