687	// ProposalsSnapshot 是同一份完整已提交状态下的登记提案与投票提案列表。
688	// 一次 ProposalsSnapshot 调用只读取一次状态文件，保证两个来源的提案状态、
689	// 动作与投票明细彼此一致：不会把不同提交时刻的提案状态拼在一起。
690	type ProposalsSnapshot struct {
691		Registered []ProposalRecord    `json:"registered"`
692		Voting     []*VoteProposalView `json:"voting"`
693	}
694	
695	// ProposalsSnapshot 在一次持锁读取中取得全部登记提案与全部投票提案。
696	// Registered 按编号排序，Voting 按编号排序；返回的切片与记录均为副本，
697	// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
698	func (s *Store) ProposalsSnapshot() (*ProposalsSnapshot, error) {
699		state, err := s.readState()
700		if err != nil {
701			return nil, err
702		}
703		return &ProposalsSnapshot{
704			Registered: proposalRecords(state),
705			Voting:     voteProposalViews(state),
706		}, nil
707	}
