709	func toProposalRecord(p *storedProposal) ProposalRecord {
710		return ProposalRecord{
711			ID:          p.ID,
712			State:       p.State,
713			TimelockEnd: p.TimelockEnd,
714			Actions:     copyActions(p.Actions),
715		}
716	}
