718	// Receipt 按编号返回执行凭据；尚未成功执行或不存在时 ok 为 false。
719	func (s *Store) Receipt(id string) (*Receipt, bool, error) {
720		state, err := s.readState()
721		if err != nil {
722			return nil, false, err
723		}
724		r := findReceipt(state.Receipts, id)
725		if r == nil {
726			return nil, false, nil
727		}
728		return cloneReceipt(r), true, nil
729	}
730	
731	// Receipts 按成功提交的先后顺序返回全部执行凭据的副本。
732	func (s *Store) Receipts() ([]*Receipt, error) {
733		state, err := s.readState()
734		if err != nil {
735			return nil, err
736		}
737		out := make([]*Receipt, 0, len(state.Receipts))
738		for _, r := range state.Receipts {
739			out = append(out, cloneReceipt(r))
740		}
741		return out, nil
742	}
