744	func (s *Store) readState() (*storedState, error) {
745		commit, err := s.begin()
746		if err != nil {
747			return nil, err
748		}
749		defer commit()
750		return s.loadLocked()
751	}
752	
753	// ---- 持久化 ----
754	
755	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
756	func (s *Store) loadLocked() (*storedState, error) {
757		raw, err := os.ReadFile(s.path)
758		if err != nil {
759			return nil, err
760		}
761		if len(bytes.TrimSpace(raw)) == 0 {
762			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
763		}
764		if err := checkStateStructure(raw); err != nil {
765			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
766		}
767		var state storedState
768		dec := json.NewDecoder(bytes.NewReader(raw))
769		dec.DisallowUnknownFields()
770		if err := dec.Decode(&state); err != nil {
771			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
772		}
773		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
774		var extra json.RawMessage
775		if err := dec.Decode(&extra); err != io.EOF {
776			if err == nil {
777				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
778			}
779			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
780		}
781		if err := validateState(&state); err != nil {
782			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
783		}
784		return &state, nil
785	}
786	
787	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
788	// 任一步失败都保留上次完整状态。调用方必须持锁。
789	func (s *Store) commitLocked(state *storedState) error {
790		if err := validateState(state); err != nil {
791			return fmt.Errorf("refusing to persist invalid state: %w", err)
792		}
793		payload, err := json.MarshalIndent(state, "", "  ")
794		if err != nil {
795			return err
796		}
797		payload = append(payload, '\n')
798	
799		dir := filepath.Dir(s.path)
800		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
801		if err != nil {
802			return err
803		}
804		tmpName := tmp.Name()
805		cleanup := func() { _ = os.Remove(tmpName) }
806		if _, err := tmp.Write(payload); err != nil {
807			_ = tmp.Close()
808			cleanup()
809			return err
810		}
811		if err := tmp.Sync(); err != nil {
812			_ = tmp.Close()
813			cleanup()
814			return err
815		}
816		if err := tmp.Close(); err != nil {
817			cleanup()
818			return err
819		}
820		if err := os.Chmod(tmpName, 0o600); err != nil {
821			cleanup()
822			return err
823		}
824		if err := os.Rename(tmpName, s.path); err != nil {
825			cleanup()
826			return err
827		}
828		if err := syncDir(dir); err != nil {
829			return err
830		}
831		return nil
832	}
833	
834	func syncDir(dir string) error {
835		d, err := os.Open(dir)
836		if err != nil {
837			return err
838		}
839		defer d.Close()
840		return d.Sync()
841	}
842	
843	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
844	func validateState(state *storedState) error {
845		if state.Magic != stateMagic {
846			return fmt.Errorf("bad magic %q", state.Magic)
847		}
848		if state.Version != stateVersion {
849			return fmt.Errorf("unsupported state version %d", state.Version)
850		}
851		if state.InitialTreasury < 0 {
852			return errors.New("initial treasury balance is negative")
853		}
854		if state.Treasury < 0 {
855			return errors.New("treasury balance is negative")
856		}
857		if state.Balances == nil {
858			return errors.New("balances table is missing")
859		}
860		if state.Proposals == nil {
861			return errors.New("proposals table is missing")
862		}
863		if state.Receipts == nil {
864			return errors.New("receipts table is missing")
865		}
866		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
867		if state.VoteProposals == nil {
868			state.VoteProposals = map[string]*storedVoteProposal{}
869		}
870		for account, balance := range state.Balances {
871			if account == "" {
872				return errors.New("balance entry with empty account")
873			}
874			if balance < 0 {
875				return fmt.Errorf("balance of %q is negative", account)
876			}
877		}
878		for key, p := range state.Proposals {
879			if p == nil {
880				return fmt.Errorf("proposal %q is empty", key)
881			}
882			if p.ID != key || p.ID == "" {
883				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
884			}
885			if p.State != "passed" && p.State != "executed" {
886				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
887			}
888			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
889		}
890		if err := validateVoteProposals(state); err != nil {
891			return err
892		}
893	
894		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
895		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
896		simTreasury := state.InitialTreasury
897		simBalances := map[string]int64{}
898		seenReceipts := map[string]int{}
899		for order, rcpt := range state.Receipts {
900			if rcpt == nil {
901				return fmt.Errorf("receipt %d is empty", order)
902			}
903			// order 是执行留痕中明确保存的成功提交序号（0 起），必须显式写出、
904			// 为 int64 范围内的非负整数且恰好等于凭据在记录表中的位置：第一份
905			// 凭据缺 order 也不能补成 0。缺失/空值/类型不符/位置不符都带提案
906			// 编号与字段报损坏，不按数组位置重新编号。
907			if err := validateReceiptOrder(order, rcpt); err != nil {
908				return err
909			}
910			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
911				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
912			}
913			seenReceipts[rcpt.ProposalID] = order
914			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
915			if !found {
916				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
917			}
918			if ownerState != "executed" {
919				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
920			}
921			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
922			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
923			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
924				return err
925			}
926			// 每项动作的 index 与四个余额字段（资金库/收款账户 × before/after）
927			// 都必须明确写出：任何一个缺失、为 null 或类型不符都判整份状态损坏，
928			// 不能按数组位置、转账金额、账户余额或其它凭据补出；明确写出的 0 是
929			// 合法记录（第一项动作的 index 0 必须显式保存）。
930			for i := range rcpt.Actions {
931				if err := validateReceiptActionIndex(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
932					return err
933				}
934				if err := validateReceiptActionBalances(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
935					return err
936				}
937			}
938			// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
939			// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
940			// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
941			// 不会被查询或落盘采纳。
942			var verr error
943			simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
944			if verr != nil {
945				return verr
946			}
947		}
948		if simTreasury != state.Treasury {
949			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
950		}
951		// 余额表的账户集合必须与成功凭据涉及的收款账户完全一致：缺少收款账户、
952		// 出现无凭据支持的账户（即使写成 0）或已记录余额不符都判整份状态损坏。
953		// 不能只按账户数量或仅遍历文件自身的键：把一个已收款账户换成数量相同、
954		// 余额写成 0 的陌生账户时，数量相等且缺失键在 map 中读到零值，会被误判
955		// 为合法。账户名排序后报告，使错误信息确定且可读；余额表的排列顺序本身
956		// 不影响判定。
957		savedAccounts := make([]string, 0, len(state.Balances))
958		for account := range state.Balances {
959			savedAccounts = append(savedAccounts, account)
960		}
961		replayAccounts := make([]string, 0, len(simBalances))
962		for account := range simBalances {
963			replayAccounts = append(replayAccounts, account)
964		}
965		sort.Strings(savedAccounts)
966		sort.Strings(replayAccounts)
967		var missing, unexpected []string
968		si, ri := 0, 0
969		for si < len(savedAccounts) || ri < len(replayAccounts) {
970			switch {
971			case ri == len(replayAccounts) || (si < len(savedAccounts) && savedAccounts[si] < replayAccounts[ri]):
972				unexpected = append(unexpected, savedAccounts[si])
973				si++
974			case si == len(savedAccounts) || savedAccounts[si] > replayAccounts[ri]:
975				missing = append(missing, replayAccounts[ri])
976				ri++
977			default:
978				si++
979				ri++
980			}
981		}
982		if len(missing) > 0 || len(unexpected) > 0 {
983			problems := ""
984			if len(missing) > 0 {
985				problems = fmt.Sprintf("missing recipient account(s) %s with no balance record for funds actually received",
986					strings.Join(quoteAccounts(missing), ", "))
987			}
988			if len(unexpected) > 0 {
989				if problems != "" {
990					problems += "; "
991				}
992				problems += fmt.Sprintf("account(s) %s have balance records but no successful receipt supports them (a zero balance does not make an unsupported account legal)",
993					strings.Join(quoteAccounts(unexpected), ", "))
994			}
995			return fmt.Errorf("balance table is inconsistent with execution receipts: %s", problems)
996		}
997		for _, account := range replayAccounts {
998			if balance := state.Balances[account]; balance != simBalances[account] {
999				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
1000			}
1001		}
1002		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
1003		for _, p := range state.Proposals {
1004			_, hasReceipt := seenReceipts[p.ID]
1005			if p.State == "executed" && !hasReceipt {
1006				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
1007			}
1008		}
1009		for _, p := range state.VoteProposals {
1010			_, hasReceipt := seenReceipts[p.ID]
1011			if p.State == "executed" && !hasReceipt {
1012				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
1013			}
1014		}
1015		return nil
1016	}
1017	
1018	// quoteAccounts 给账户名列表逐个加上 Go 风格引号，便于在损坏原因中逐字定位。
1019	func quoteAccounts(accounts []string) []string {
1020		quoted := make([]string, len(accounts))
1021		for i, account := range accounts {
1022			quoted[i] = strconv.Quote(account)
1023		}
1024		return quoted
1025	}
1026	
1027	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
1028	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
1029	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
1030	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
1031	// 位置（0 起），与提案编号一起用于定位。
1032	// “缺失/空值/类型不符”的判定与逐票明细、计票结果共用同一份规则
1033	// （requiredScalarProblem），此处只补充凭据的业务位置与执行资格检查。
1034	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
1035		if problem := requiredScalarProblem(rcpt.executedAtRaw, scalarInteger); problem != "" {
1036			return fmt.Errorf("receipt %d for proposal %q field %q %s", order, rcpt.ProposalID, "executed_at", problem)
1037		}
1038		if rcpt.ExecutedAt < timelockEnd {
1039			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
1040				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
1041		}
1042		return nil
1043	}
1044	
1045	// validateReceiptOrder 严格判定一份已保存凭据的 order：它是执行留痕中明确
1046	// 保存的成功提交序号（0 起），字段未写出、显式为 null 或不是 int64 整数都
1047	// 返回带提案编号与字段的错误；类型合法但值与凭据在记录表中的实际位置不符
1048	// （含负数）则返回位置不符的错误。第一份凭据恰好排在位置 0 也不能因此把
1049	// 缺失字段补成 0——明确写出的 0 才是合法序号，缺失/null/写错类型一律拒绝。
1050	// position 是凭据在凭据表中的位置（0 起）。
1051	func validateReceiptOrder(position int, rcpt *Receipt) error {
1052		if problem := requiredScalarProblem(rcpt.orderRaw, scalarInteger); problem != "" {
1053			return fmt.Errorf("receipt %d for proposal %q field %q %s",
1054				position, rcpt.ProposalID, "order", problem)
1055		}
1056		if rcpt.Order != int64(position) {
1057			return fmt.Errorf("receipt %d for proposal %q field %q is %d, expected %d",
1058				position, rcpt.ProposalID, "order", rcpt.Order, position)
1059		}
1060		return nil
1061	}
1062	
1063	// validateReceiptActionIndex 严格判定一条动作留痕的 index：它是该动作在所属
1064	// 凭据中明确保存的位置编号（0 起）。字段未写出、显式为 null 或不是 int64
1065	// 整数（字符串、布尔、小数、指数写法、超界）返回带提案编号、动作位置与
1066	// 字段的错误；类型合法但值与动作的实际位置不符（含负数）返回位置不符错误。
1067	// 第一项动作缺失 index 不得被补成 0：只有明确写出的 0 才合法。position 是
1068	// 动作在凭据 actions 中的位置（0 起）。
1069	func validateReceiptActionIndex(id string, position int, ar *ActionReceipt) error {
1070		if problem := requiredScalarProblem(ar.indexRaw, scalarInteger); problem != "" {
1071			return fmt.Errorf("receipt for proposal %q action %d field %q %s",
1072				id, position, "index", problem)
1073		}
1074		if ar.Index != int64(position) {
1075			return fmt.Errorf("receipt for proposal %q action %d field %q is %d, expected %d",
1076				id, position, "index", ar.Index, position)
1077		}
1078		return nil
1079	}
1080	
1081	// validateReceiptActionBalances 严格判定一条动作留痕的四个余额字段：
1082	// 资金库与收款账户两侧的 before/after 都必须明确写出、非 null 且为 int64
1083	// 整数。任何一个字段缺失都判整份状态损坏，不能根据转账金额、账户余额或
1084	// 其它凭据补出它——即使按其余记录推算该字段本来应为 0。明确写出的整数 0
1085	// 是合法记录（如资金库恰好扣到 0、收款账户首次收款前为 0），不得当成缺失。
1086	// index 是动作在凭据中的下标（0 起），与提案编号、所在侧一起用于定位。
1087	// “缺失/空值/类型不符”的判定与逐票明细、计票结果、executed_at 共用同一份
1088	// 规则（validateRawFields），此处只补充业务位置：提案编号 + 动作下标 + 侧。
1089	func validateReceiptActionBalances(id string, index int, ar *ActionReceipt) error {
1090		sides := []struct {
1091			name   string
1092			update *BalanceUpdate
1093		}{
1094			{"treasury", &ar.Treasury},
1095			{"recipient", &ar.Recipient},
1096		}
1097		for _, side := range sides {
1098			err := validateRawFields([]rawField{
1099				{name: "before", kind: scalarInteger, raw: side.update.beforeRaw},
1100				{name: "after", kind: scalarInteger, raw: side.update.afterRaw},
1101			}, func(field, problem string) error {
1102				return fmt.Errorf("receipt for proposal %q action %d %s field %q %s",
1103					id, index, side.name, field, problem)
1104			})
1105			if err != nil {
1106				return err
1107			}
1108		}
1109		return nil
1110	}
1111	
1112	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
1113	
1114	// schemaKind 是状态文件 JSON 在某一层的形状类别。
1115	type schemaKind int
1116	
1117	const (
1118		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
1119		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
1120		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
1121		kindArray                     // 数组
1122		kindString                    // 叶子：必须是 JSON 字符串
1123		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
1124		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
1125	)
1126	
1127	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
1128	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
1129	type schemaNode struct {
1130		kind   schemaKind
1131		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
1132		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
1133	}
1134	
1135	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
1136	func schemaOf(t reflect.Type) *schemaNode {
1137		for t.Kind() == reflect.Pointer {
1138			t = t.Elem()
1139		}
1140		switch t.Kind() {
1141		case reflect.Struct:
1142			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1143			for i := 0; i < t.NumField(); i++ {
1144				f := t.Field(i)
1145				if f.PkgPath != "" { // 未导出字段不参与 JSON
1146					continue
1147				}
1148				name := f.Name
1149				if tag, ok := f.Tag.Lookup("json"); ok {
1150					tagName, _, _ := strings.Cut(tag, ",")
1151					if tagName == "-" {
1152						continue
1153					}
1154					if tagName != "" {
1155						name = tagName
1156					}
1157				}
1158				node.fields[name] = schemaOf(f.Type)
1159			}
1160			return node
1161		case reflect.Map:
1162			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1163		case reflect.Slice, reflect.Array:
1164			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1165		case reflect.String:
1166			return &schemaNode{kind: kindString}
1167		case reflect.Bool:
1168			return &schemaNode{kind: kindBoolean}
1169		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1170			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1171			return &schemaNode{kind: kindInteger}
1172		default:
1173			return &schemaNode{kind: kindAny}
1174		}
1175	}
1176	
1177	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1178	
1179	func init() {
1180		// 票据的四个标量字段（representative/weight/support/voted_at）由
1181		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1182		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1183		// 不抢在解码器之前用不含票据定位的通用信息报错。
1184		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1185		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1186			ballotFields[name].kind = kindAny
1187		}
1188		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
1189		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
1190		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
1191		// 其“不早于截止”的既有校验不变。
1192		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1193		for _, name := range []string{"for_weight", "against_weight"} {
1194			tallyFields[name].kind = kindAny
1195		}
1196		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1197		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1198		// 叶子位置保持宽松。
1199		receiptFields := storedStateSchema.fields["receipts"].elem.fields
1200		receiptFields["executed_at"].kind = kindAny
1201		// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
1202		// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
1203		receiptFields["order"].kind = kindAny
1204		// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
1205		// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
1206		// 此叶子位置保持宽松。
1207		receiptFields["actions"].elem.fields["index"].kind = kindAny
1208		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1209		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1210		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
1211		actionFields := receiptFields["actions"].elem.fields
1212		for _, side := range []string{"treasury", "recipient"} {
1213			balanceFields := actionFields[side].fields
1214			balanceFields["before"].kind = kindAny
1215			balanceFields["after"].kind = kindAny
1216		}
1217	}
